spec.code:
const orden = aws.cfn.dependencyOrder(template);
assert.ok(orden !== null, "La plantilla no tiene un orden de creación");
assert.ok(orden.indexOf("GrupoWeb") < orden.indexOf("InstanciaWeb"), "GrupoWeb debe crearse antes que InstanciaWeb");

const instancia = JSON.stringify(template.Resources.InstanciaWeb);
assert.ok(instancia.includes('"SecurityGroupIds":[{"Ref":"GrupoWeb"}]'), "La instancia debe referenciar el grupo con Ref");
assert.ok(instancia.includes('{"Ref":"Entorno"}'), "La etiqueta debe usar Ref hacia Entorno");

