// Plantilla del entorno regional: un grupo de seguridad, una instancia y una base de datos.
export const template = {
  AWSTemplateFormatVersion: "2012-10-17",
  Description: "Entorno regional repetible",
  Parameters: {
    Entorno: { Type: "String" },
  },
  Resources: {
    GrupoWeb: {
      Type: "AWS::EC2::SecurityGroup",
      Properties: {
        GroupDescription: "Acceso web del entorno",
        SecurityGroupIngress: [
          { IpProtocol: "tcp", FromPort: 22, ToPort: 22, CidrIp: "0.0.0.0/0" },
          { IpProtocol: "tcp", FromPort: 443, ToPort: 443, CidrIp: "0.0.0.0/0" },
        ],
        Tags: [{ Key: "base", Value: { Ref: "BaseDatos" } }],
      },
    },
    InstanciaWeb: {
      Type: "AWS::EC2::Instance",
      Properties: {
        SecurityGroupIds: [{ Ref: "GrupoWeb" }],
        Tags: [{ Key: "Name", Value: { "Fn::Sub": "web-${Entorno}" } }],
      },
    },
    BaseDatos: {
      Type: "AWS::RDS::DBInstance",
      Properties: {
        VPCSecurityGroups: [{ "Fn::GetAtt": ["GrupoWeb", "GroupId"] }],
      },
    },
  },
  Outputs: {
    IdInstancia: { Value: { Ref: "InstanciaWeb" } },
    PuntoFinalBase: { Value: { "Fn::GetAtt": "BaseDatos.Endpoint.Address" } },
  },
};

