// Vía de acceso que elige un asistente para cuatro escenarios. Corrige la elección equivocada.
export const eleccion = {
  escenarios: [
    { necesidad: "Explorar un servicio nuevo con una interfaz web", via: "consola" },
    { necesidad: "Ejecutar cada noche un script de shell que gestione recursos", via: "cli" },
    { necesidad: "Crear el mismo entorno en varias Regiones y eliminarlo después como un conjunto", via: "plantilla" },
    { necesidad: "Ejecutar comandos de la CLI sin salir de la consola web", via: "cloudshell" },
  ],
};

spec.code:
const fila = eleccion.escenarios.find((f) => f.necesidad.startsWith("Crear el mismo entorno"));
assert.ok(fila, "debe existir la fila del entorno repetible");
assert.strictEqual(fila.via, "plantilla");

for (const fila of eleccion.escenarios) {
  assert.ok(["consola", "cli", "cloudshell", "plantilla"].includes(fila.via), fila.necesidad + " tiene una vía no válida");
}

const esperado = {
  "Explorar un servicio nuevo con una interfaz web": "consola",
  "Ejecutar cada noche un script de shell que gestione recursos": "cli",
  "Ejecutar comandos de la CLI sin salir de la consola web": "cloudshell",
};
for (const [necesidad, via] of Object.entries(esperado)) {
  const fila = eleccion.escenarios.find((f) => f.necesidad === necesidad);
  assert.ok(fila, necesidad + " debe seguir existiendo");
  assert.strictEqual(fila.via, via);
}
